<?php require_once __DIR__.'/includes/images.php';require_once __DIR__.'/includes/database.php';require_once __DIR__.'/includes/functions.php';$pageTitle=t('Contact','እውቂያ');$message=flash('message');if(is_post()){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$body=trim($_POST['message']??'');if($body===''){flash('message',t('Please enter a message.','እባክዎ መልእክትዎን ያስገቡ።'));}elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('message',t('Please enter a valid email.','እባክዎ ትክክለኛ ኢሜይል ያስገቡ።'));}else{try{$st=db()->prepare('INSERT INTO contact_messages(name,email,subject,message,status) VALUES(?,?,?,?,?)');$st->execute([$name?:null,$email?:null,$subject?:null,$body,'new']);flash('message',t('Your message has been sent. Thank you.','መልእክትዎ ተልኳል። እናመሰግናለን።'));}catch(Throwable $e){flash('message',t('Could not send the message. Please try again later.','መልእክቱን መላክ አልተቻለም። ቆይተው ይሞክሩ።'));}}redirect('contact.php');}require __DIR__.'/includes/header.php';?>
<section class="page-hero page-hero-image" style="<?=e(hero_style('contact'))?>"><div class="container"><span class="eyebrow"><?=e(t('Home / Contact','መነሻ / እውቂያ'))?></span><h1><?=e(t('Contact Us','ያግኙን'))?></h1><p><?=e(t('Connect with the fellowship team, visit the campus or follow us online.','ከፌሎሽፕ ቡድን ጋር ይገናኙ፣ ካምፓሱን ይጎብኙ ወይም በመስመር ላይ ይከተሉን።'))?></p></div></section><section class="section"><div class="container two-col"><div class="form-card"><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif;?><form method="post" class="form-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Name / ስም<input name="name" maxlength="120"></label><label>Email / ኢሜይል<input type="email" name="email" maxlength="150"></label><label>Subject / ርዕስ<input name="subject" maxlength="255"></label><label>Message / መልእክት<textarea name="message" rows="8" required maxlength="5000"></textarea></label><button class="btn primary">Send Message / መልእክት ይላኩ</button></form></div><div><div class="about-photo-card" style="min-height:420px"><img src="<?=e(content_image('contact','contact'))?>" alt="Contact fellowship"><div><span>CONNECT WITH US</span><b>Telegram · TikTok · Instagram · Facebook</b></div></div></div></div></section><?php require __DIR__.'/includes/footer.php';?>
